#include <stdio.h>
#include <stdlib.h>

void alloc(int **out, size_t n) {
    *out = malloc(n * sizeof(int));
    for (size_t i = 0; i < n; i++) (*out)[i] = (int)(i * i);
}

int main(void) {
    int *buf = NULL;
    alloc(&buf, 5);
    if (!buf) return 1;
    for (size_t i = 0; i < 5; i++) printf("%d ", buf[i]);
    printf("\n");
    free(buf);
    buf = NULL;
    return 0;
}
